import openpyxl, os, re
from openpyxl.utils import get_column_letter

src_path='/root/data/workbook.xlsx'
out_path='/root/output/result.xlsx'

wb=openpyxl.load_workbook(src_path, data_only=False)
print('Loaded', src_path)
print('Sheets:', wb.sheetnames)

# Identify Task and Data sheets by name (case-insensitive match)

def find_sheet(keywords):
    for s in wb.sheetnames:
        sl=s.lower()
        if any(k in sl for k in keywords):
            return wb[s]
    return None

task_ws=find_sheet(['task']) or wb[wb.sheetnames[0]]
data_ws=find_sheet(['data'])
print('Task sheet:', task_ws.title)
print('Data sheet:', data_ws.title if data_ws else None)

# Inspect Task layout: check row 10 years in H-L, series codes in column D
for col in ['H','I','J','K','L']:
    v=task_ws[f'{col}10'].value
    print(f'Task!{col}10 = {v!r}')

print('Series codes sample:')
for r in list(range(12,18))+list(range(19,25))+list(range(26,32)):
    print(f'Task!D{r} = {task_ws[f"D{r}"].value!r}')

# Confirm highlight fills (yellow-ish) in target ranges (print fgColor repr)
ranges=[('H12','L17'),('H19','L24'),('H26','L31'),('H35','L40'),('H42','L47'),('H50','L50')]

def fill_sig(cell):
    fill=cell.fill
    if fill is None or fill.patternType is None:
        return None
    c=fill.fgColor
    if c is None:
        return None
    if c.type=='rgb':
        return c.rgb
    if c.type=='indexed':
        return f'indexed:{c.indexed}'
    if c.type=='theme':
        return f'theme:{c.theme}:{c.tint}'
    return str(c)

print('\nSample fill colors (top-left of each target range):')
for a,b in ranges:
    cell=task_ws[a]
    print(f'{a}:{b} top-left {a} fill -> {fill_sig(cell)}')

# Inspect Data table
if data_ws is None:
    raise SystemExit('No Data sheet found')

print('\nData row 20 sample A-P:')
for col in range(1,17):
    addr=f'{get_column_letter(col)}20'
    print(addr, data_ws[addr].value)

print('\nData col A rows 20-40 sample:')
for r in range(20,41):
    print(f'A{r}', data_ws[f'A{r}'].value)

# Detect header row for years
header_row=None
for r in range(15,26):
    vals=[data_ws[f'{get_column_letter(c)}{r}'].value for c in range(2,60)]
    yearish=[v for v in vals if isinstance(v,(int,float)) and 1900<=v<=2100]
    if len(yearish)>=3:
        header_row=r
        break
print('\nDetected Data header row:', header_row)
if header_row is None:
    raise SystemExit('Could not detect Data header row with years')

# Determine last column by scanning header row until 3 consecutive blanks
last_col=None
blanks=0
for c in range(2,201):
    v=data_ws[f'{get_column_letter(c)}{header_row}'].value
    if v is None or v=='':
        blanks+=1
        if blanks>=3:
            last_col=c-3
            break
    else:
        blanks=0
if last_col is None:
    last_col=50

# Determine table bounds: start_row=21; find last_row by blanks
start_row=21
last_row=None
blanks=0
for r in range(start_row,201):
    v=data_ws[f'A{r}'].value
    if v is None or v=='':
        blanks+=1
        if blanks>=2:
            last_row=r-2
            break
    else:
        blanks=0
if last_row is None:
    last_row=38

print('Data table rows:', start_row,'to',last_row)
print('Data table last column:', last_col, get_column_letter(last_col))

print('\nSample Data intersections:')
for rr in range(start_row, min(start_row+3,last_row+1)):
    code=data_ws[f'A{rr}'].value
    year=data_ws[f'B{header_row}'].value
    val=data_ws[f'B{rr}'].value
    print(f'code {code!r}, year {year!r}, value at B{rr} -> {val!r}')

# Look at Task labels for rows 42-47
print('\nTask rows 42-47 labels (col D plus nearby):')
for r in range(42,48):
    vals={c:task_ws[f'{c}{r}'].value for c in ['C','D','E']}
    print(r, vals)

# Detect percentile function style already used
found_inc=found_exc=found_plain=False
for ws in wb.worksheets:
    for row in ws.iter_rows():
        for cell in row:
            v=cell.value
            if isinstance(v,str) and v.startswith('='):
                u=v.upper()
                if 'PERCENTILE.INC' in u:
                    found_inc=True
                if 'PERCENTILE.EXC' in u:
                    found_exc=True
                if re.search(r'\bPERCENTILE\b', u) and 'PERCENTILE.' not in u:
                    found_plain=True

if found_inc and not found_exc:
    percentile_style='PERCENTILE.INC'
elif found_exc and not found_inc:
    percentile_style='PERCENTILE.EXC'
else:
    percentile_style='PERCENTILE'
print('\nDetected percentile style in workbook:', percentile_style, '(inc:',found_inc,'exc:',found_exc,'plain:',found_plain,')')

# --- Write formulas ---
from openpyxl.utils.cell import range_boundaries

last_col_letter=get_column_letter(last_col)
index_range=f'Data!$B${start_row}:${last_col_letter}${last_row}'
row_match_range=f'Data!$A${start_row}:$A${last_row}'
col_match_range=f'Data!$B${header_row}:${last_col_letter}${header_row}'
print('\nUsing ranges:')
print('INDEX:', index_range)
print('Row MATCH:', row_match_range)
print('Col MATCH:', col_match_range)


def fill_lookup_block(rng):
    min_col, min_row, max_col, max_row = range_boundaries(rng)
    for r in range(min_row, max_row+1):
        for c in range(min_col, max_col+1):
            col_letter=get_column_letter(c)
            formula=f"=INDEX({index_range}, MATCH($D{r},{row_match_range},0), MATCH({col_letter}$10,{col_match_range},0))"
            task_ws.cell(row=r, column=c).value=formula

fill_lookup_block('H12:L17')
fill_lookup_block('H19:L24')
fill_lookup_block('H26:L31')
print('Filled lookup blocks H12:L17, H19:L24, H26:L31.')

# Headroom
min_col, min_row, max_col, max_row = range_boundaries('H35:L40')
for r in range(min_row, max_row+1):
    i=r-35
    avail=12+i
    occ=19+i
    cap=26+i
    for c in range(min_col, max_col+1):
        col_letter=get_column_letter(c)
        task_ws.cell(row=r, column=c).value=f"=({col_letter}{avail}-{col_letter}{occ})/{col_letter}{cap}*100"
print('Filled headroom H35:L40.')

# Stats mapping by labels
label_map={}
for r in range(42,48):
    lab=task_ws[f'D{r}'].value
    if isinstance(lab,str):
        label_map[r]=lab.strip().lower()

stat_row_by_kind={}
for r,lab in label_map.items():
    if 'min' in lab:
        stat_row_by_kind['min']=r
    if 'max' in lab:
        stat_row_by_kind['max']=r
    if 'median' in lab:
        stat_row_by_kind['median']=r
    if 'mean' in lab or 'average' in lab or 'avg' in lab:
        stat_row_by_kind['average']=r
    if '25' in lab or 'q1' in lab or 'lower' in lab and 'quart' in lab:
        stat_row_by_kind['p25']=r
    if '75' in lab or 'q3' in lab or 'upper' in lab and 'quart' in lab:
        stat_row_by_kind['p75']=r

fallback_order=['min','max','median','average','p25','p75']
for kind,r in zip(fallback_order, range(42,48)):
    stat_row_by_kind.setdefault(kind,r)

print('Stats row mapping:', stat_row_by_kind)

for col in ['H','I','J','K','L']:
    rng=f'{col}35:{col}40'
    task_ws[f'{col}{stat_row_by_kind["min"]}'].value=f"=MIN({rng})"
    task_ws[f'{col}{stat_row_by_kind["max"]}'].value=f"=MAX({rng})"
    task_ws[f'{col}{stat_row_by_kind["median"]}'].value=f"=MEDIAN({rng})"
    task_ws[f'{col}{stat_row_by_kind["average"]}'].value=f"=AVERAGE({rng})"
    task_ws[f'{col}{stat_row_by_kind["p25"]}'].value=f"={percentile_style}({rng},0.25)"
    task_ws[f'{col}{stat_row_by_kind["p75"]}'].value=f"={percentile_style}({rng},0.75)"
print('Filled stats H42:L47.')

# Weighted mean
for col in ['H','I','J','K','L']:
    task_ws[f'{col}50'].value=f"=SUMPRODUCT({col}35:{col}40, {col}26:{col}31) / SUM({col}26:{col}31)"
print('Filled weighted mean H50:L50.')

wb.save(out_path)
print('Saved to', out_path)

# --- Validation ---
wb2=openpyxl.load_workbook(out_path, data_only=False)
print('\nReopened saved workbook. Sheets:', wb2.sheetnames)

task2=wb2[task_ws.title]

from openpyxl.utils.cell import range_boundaries

def check_range(rng):
    min_col, min_row, max_col, max_row = range_boundaries(rng)
    empty=[]
    non_formula=[]
    for r in range(min_row, max_row+1):
        for c in range(min_col, max_col+1):
            v=task2.cell(row=r,column=c).value
            if v is None or v=='':
                empty.append(f'{get_column_letter(c)}{r}')
            elif not (isinstance(v,str) and v.startswith('=')):
                non_formula.append((f'{get_column_letter(c)}{r}',v))
    return empty, non_formula

for rng in ['H12:L17','H19:L24','H26:L31','H35:L40','H42:L47','H50:L50']:
    empty, non_formula=check_range(rng)
    print(f'Check {rng}: empty={len(empty)} non_formula={len(non_formula)}')
    if empty:
        print('  empty sample:', empty[:5])
    if non_formula:
        print('  non_formula sample:', non_formula[:3])

print('\nSpot-check I12:', task2['I12'].value)
print('  has I$10:', 'I$10' in (task2['I12'].value or ''))
print('  has $D12:', '$D12' in (task2['I12'].value or ''))

# Ensure no extra sheets
print('\nSheet count original vs saved:', len(wb.sheetnames), 'vs', len(wb2.sheetnames))
print('Sheet names identical:', wb.sheetnames==wb2.sheetnames)

